import pandas as pd
import numpy as np

# Better marker expression summary
immune_markers = ['CD3D', 'CD3E', 'CD4', 'CD8A', 'CD19', 'CD79A', 'CD14', 'CD68', 'CD74', 'HLA-DRA', 'HLA-DRB1', 'MS4A1', 'CD16', 'CD56', 'NCAM1', 'CD34', 'C1QA', 'C3', 'LYZ', 'FCGR3A']

print("=== Marker Expression by Cluster ===")
marker_summary = {}
for gene in immune_markers:
    if gene in adata.var_names:
        expr = adata[:, adata.var_names == gene].X.toarray().flatten() if hasattr(adata.X, 'toarray') else adata.X.flatten()
        for cluster_id in adata.obs['leiden'].unique():
            mask = adata.obs['leiden'] == cluster_id
            mean_expr = expr[mask].mean()
            if cluster_id not in marker_summary:
                marker_summary[cluster_id] = {}
            marker_summary[cluster_id][gene] = mean_expr

# Convert to DataFrame
df = pd.DataFrame(marker_summary).T
print(df.round(4))

import pandas as pd
import numpy as np

# More comprehensive marker analysis
print("=== Detailed Marker Expression by Cluster ===")
markers = {
    'T_cells': ['CD3D', 'CD3E', 'CD4', 'CD8A', 'TRAC', 'TRBC1'],
    'Myeloid': ['CD14', 'CD68', 'LYZ', 'FCGR3A', 'CD16', 'C1QA', 'C1QB', 'C3'],
    'B_cells': ['CD19', 'CD79A', 'CD79B', 'MS4A1', 'CD20'],
    'NK_cells': ['NCAM1', 'CD56', 'GZMB', 'NKG7'],
    'Dendritic': ['HLA-DRA', 'HLA-DRB1', 'CD74', 'FCER1A'],
    'Endothelial': ['CDH5', 'VWF', 'PECAM1', 'CLDN5']
}

all_markers = []
for category, genes in markers.items():
    for gene in genes:
        if gene in adata.var_names:
            all_markers.append(gene)

marker_summary = {}
for gene in all_markers:
    expr = adata[:, adata.var_names == gene].X.toarray().flatten() if hasattr(adata.X, 'toarray') else adata.X.flatten()
    for cluster_id in adata.obs['leiden'].unique():
        mask = adata.obs['leiden'] == cluster_id
        mean_expr = expr[mask].mean()
        if cluster_id not in marker_summary:
            marker_summary[cluster_id] = {}
        marker_summary[cluster_id][gene] = mean_expr

df = pd.DataFrame(marker_summary).T
print(df.round(3))

print("\n=== Cluster Sizes ===")
print(adata.obs['leiden'].value_counts().sort_index())
